// @MARKER addHighAuraRegenBoost (sheet-worker.js:96533)
	function addHighAuraRegenBoost(tempAuraRegenRate, tempAuraRegenBonus) {
		tmpNewAuraRegen="";
		if (tempAuraRegenRate.includes("per Second")) { // we will add to the seconds. 
			tmpStandardRegenNum=parseInt(tempAuraRegenRate.match(/\d+/)?.shift());
			tempAuraRegenBonus=tempAuraRegenBonus.slice(1);
			tmpModBoostNum=parseInt(tempAuraRegenBonus.match(/\d+/)?.shift());			
			newModNum=parseInt([tmpStandardRegenNum+tmpModBoostNum]);
			tmpNewAuraRegen=""+newModNum+"/per Second";
		} else {  // the High Aura regen boost is way over the current one and so supplants it. 
			tmpNewAuraRegen=tempAuraRegenBonus;
		}
		return tmpNewAuraRegen;
	}

