// @MARKER checkDevotion (sheet-worker.js:152688)
	export function checkDevotion(tempInvocationName, tmpCurrentDevotion) {
		tempFoundIn=false;
		devotionList=getDevotionList(tmpCurrentDevotion);
		devotionListArray=devotionList.split(",");
		for (var i=0; i<devotionListArray.length; i++) {
			if (tempInvocationName==devotionListArray[i])  {
				tempFoundIn=true;
				i=devotionListArray.length;
			}
		}
		return tempFoundIn;
	}

