// @MARKER getHalfCastingTime (sheet-worker.js:170511)
	export function getHalfCastingTime(tempSpellCastTime) {
		tempNewCastingTime="";
		tempCastTimeValue=parseInt(tempSpellCastTime);
		tempCastTimeValue2=parseFloat(tempCastTimeValue+0.9);
		tempCastTimeType=tempSpellCastTime.replace(""+tempCastTimeValue+" ","");
		newCastTimeValue=divideWithMin(tempCastTimeValue2, 2);
		tempNewCastingTime=""+newCastTimeValue+" "+tempCastTimeType;
		return tempNewCastingTime;
	}

